head.b:skin:
:root{--cream:#F6F1E8;--ink:#20201E;--terra:#D85C4A;--sage:#A8B5A2;--blue:#8DA4B8;--yellow:#E4B85E;--white:#fff;--muted:#6F6B63;--line:#DED7CA;--radius:22px;--shadow:0 18px 45px rgba(32,32,30,.08)}
*{box-sizing:border-box}html{scroll-behavior:smooth}body{margin:0;background:var(--cream);color:var(--ink);font-family:Inter,Arial,Helvetica,sans-serif;line-height:1.65}a{color:inherit;text-decoration:none}img{max-width:100%;height:auto;display:block}.container{width:min(1180px,92vw);margin:auto}
.topbar{border-bottom:1px solid var(--line);font-size:12px;color:var(--muted);letter-spacing:.08em;text-transform:uppercase}.topbar-inner{display:flex;justify-content:space-between;gap:20px;padding:10px 0}.brand-row{display:flex;align-items:center;justify-content:space-between;gap:24px;padding:24px 0}.brand{font-size:34px;line-height:1;font-weight:900;letter-spacing:-.06em}.brand small{display:block;margin-top:8px;font-size:11px;font-weight:700;letter-spacing:.22em;color:var(--muted)}
.nav{border-top:1px solid var(--line);border-bottom:1px solid var(--line);overflow:auto}.nav ul{display:flex;gap:24px;list-style:none;margin:0;padding:14px 0;white-space:nowrap}.nav a{font-size:13px;font-weight:800;letter-spacing:.04em}.nav a:hover{color:var(--terra)}
.hero{display:grid;grid-template-columns:1.35fr .65fr;gap:24px;padding:34px 0}.hero-card{min-height:430px;border-radius:var(--radius);overflow:hidden;position:relative;background:#ddd}.hero-card img{width:100%;height:100%;object-fit:cover}.hero-copy{position:absolute;inset:auto 0 0;padding:38px;color:#fff;background:linear-gradient(180deg,transparent,rgba(0,0,0,.72))}.hero-copy .eyebrow{font-size:12px;font-weight:800;letter-spacing:.16em;text-transform:uppercase}.hero-copy h1{margin:8px 0;font-size:clamp(38px,5vw,72px);line-height:.98;letter-spacing:-.055em}.hero-side{display:grid;gap:24px}.mini-card{border-radius:var(--radius);padding:28px;background:var(--white);box-shadow:var(--shadow);display:flex;flex-direction:column;justify-content:flex-end;min-height:203px}.mini-card h2{font-size:27px;line-height:1.05;margin:8px 0}.tag{display:inline-flex;align-items:center;width:max-content;padding:7px 10px;border-radius:999px;background:var(--sage);font-size:11px;font-weight:900;text-transform:uppercase;letter-spacing:.08em}
.section{padding:36px 0}.section-head{display:flex;justify-content:space-between;align-items:end;gap:20px;margin-bottom:18px}.section-head h2{margin:0;font-size:34px;line-height:1;letter-spacing:-.05em}.section-head a{font-size:12px;font-weight:900;text-transform:uppercase;letter-spacing:.1em;color:var(--terra)}.grid-3{display:grid;grid-template-columns:repeat(3,1fr);gap:22px}.grid-4{display:grid;grid-template-columns:repeat(4,1fr);gap:18px}.post-card{background:var(--white);border-radius:18px;overflow:hidden;box-shadow:var(--shadow)}.post-card .thumb{aspect-ratio:4/3;background:#ddd;overflow:hidden}.post-card .thumb img{width:100%;height:100%;object-fit:cover}.post-card .body{padding:18px}.post-card h3{margin:10px 0 0;font-size:21px;line-height:1.12;letter-spacing:-.03em}.meta{font-size:11px;text-transform:uppercase;letter-spacing:.12em;color:var(--muted);font-weight:800}
.feature-band{background:var(--ink);color:#fff;border-radius:var(--radius);padding:36px}.feature-band h2{font-size:38px;line-height:1;margin:0 0 10px}.feature-band p{color:#d6d2c8;margin:0}.pill-row{display:flex;flex-wrap:wrap;gap:10px;margin-top:22px}.pill{background:#2d2d29;padding:9px 13px;border-radius:999px;font-size:12px;font-weight:800}
.content-wrap{display:grid;grid-template-columns:minmax(0,1fr) 300px;gap:36px;padding:50px 0}.post-single{background:transparent}.post-single h1{font-size:clamp(42px,6vw,72px);line-height:.98;letter-spacing:-.06em;margin:0 0 18px}.post-body{font-size:18px;line-height:1.8}.post-body h2{font-size:34px;line-height:1.1;letter-spacing:-.04em;margin-top:45px}.post-body h3{font-size:25px}.post-body blockquote{border-left:5px solid var(--terra);padding:15px 20px;background:#fff;border-radius:0 14px 14px 0}.post-body img{border-radius:18px;margin:22px 0}.sidebar{position:sticky;top:20px;height:max-content}.widget{background:#fff;padding:22px;border-radius:18px;margin-bottom:18px;box-shadow:var(--shadow)}.widget h3{margin-top:0;font-size:15px;text-transform:uppercase;letter-spacing:.12em}.widget ul{list-style:none;padding:0;margin:0}.widget li{padding:9px 0;border-bottom:1px solid var(--line)}
.footer{margin-top:60px;background:#191917;color:#eee;padding:55px 0}.footer-grid{display:grid;grid-template-columns:2fr 1fr 1fr;gap:40px}.footer h3{font-size:32px;line-height:1;margin:0 0 10px}.footer p,.footer a{color:#bdb8ae}.footer-links{display:grid;gap:8px}.copyright{border-top:1px solid #34342f;margin-top:30px;padding-top:20px;font-size:12px;color:#8d8981}
.search{font-size:13px;font-weight:800;border:1px solid var(--line);border-radius:999px;padding:10px 15px;background:#fff}.mobile-note{display:none}
@media(max-width:900px){.hero{grid-template-columns:1fr}.grid-3{grid-template-columns:repeat(2,1fr)}.grid-4{grid-template-columns:repeat(2,1fr)}.content-wrap{grid-template-columns:1fr}.sidebar{position:static}.footer-grid{grid-template-columns:1fr 1fr}}
@media(max-width:620px){.brand-row{align-items:flex-start}.brand{font-size:29px}.search{display:none}.grid-3,.grid-4{grid-template-columns:1fr}.hero-card{min-height:360px}.hero-copy{padding:24px}.hero-copy h1{font-size:42px}.section-head h2{font-size:28px}.footer-grid{grid-template-columns:1fr}.mobile-note{display:block;font-size:11px;color:var(--muted)}}
